From 0a8761762ac78f2db2ba37f712f2a52a404ce011 Mon Sep 17 00:00:00 2001
From: Andris Reinman <andris@reinman.eu>
Date: Sun, 18 Oct 2026 14:22:38 +0300
Subject: [PATCH] fix(addressparser): end a comment only at the ")" that closes
 the outermost one

Comments nest (RFC 5322 3.2.2), but the tokenizer ended a comment at the
first ')', so the ')' of a nested comment closed the outer one and the
rest of it was parsed as header text, the address it held included.
'Victim (x(y) <evil@evil.com>) <v@victim.com>' delivered to evil.com
where every conformant reading names v@victim.com, the same shape as the
escaped parenthesis fixed in 10.1.2 reached through nesting instead of a
quoted-pair.

The tokenizer now counts the depth of the comments nested in the one it
is collecting. An escaped '(' or ')' does not count, and an unclosed
nested comment runs to the end of the value as an unclosed one does.

Differential fuzz over 812k unique inputs against the previous commit:
31126 parses change, every one holds two or more '('. Of the changed
parses Python's email package reads without defects, the recipient
domains now agree with it in 2316 of 2327 cases, against 171 before.

Fixes GHSA-8c8m-p3m8-cjg8

Co-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>
---
 src/addressparser/index.ts               | 17 +++++++--
 test/addressparser/addressparser-test.ts | 44 ++++++++++++++++++++++++
 test/mime-node/mime-node-test.ts         |  7 ++++
 3 files changed, 66 insertions(+), 2 deletions(-)

diff --git a/src/addressparser/index.ts b/src/addressparser/index.ts
index 3d5e2423..8365cfcb 100644
--- a/src/addressparser/index.ts
+++ b/src/addressparser/index.ts
@@ -681,7 +681,10 @@ class Tokenizer {
     afterAt: boolean;
     /** A quoted string is open inside the angle-addr or group being collected */
     innerQuoted: boolean;
-    /** Comment depth inside the angle-addr or group being collected */
+    /**
+     * Comment depth inside the angle-addr or group being collected, or of the comments nested
+     * in the comment being collected
+     */
     innerComment: number;
     /** A domain literal is open inside the angle-addr being collected */
     innerLiteral: boolean;
@@ -783,6 +786,16 @@ class Tokenizer {
         let nested = false;
         if (this.operatorExpecting === '>' || this.operatorExpecting === ';') {
             nested = this._trackInner(chr);
+        } else if (this.operatorExpecting === ')' && !this.escaped) {
+            // Comments nest (RFC 5322 3.2.2). Ending one at the first ')' let the ')' of a
+            // nested comment close the outer one and released the rest of it, an address
+            // included, into the header
+            if (chr === '(') {
+                this.innerComment++;
+            } else if (chr === ')' && this.innerComment) {
+                this.innerComment--;
+                nested = true;
+            }
         }

         if (this.escaped) {
@@ -920,7 +933,7 @@ class Tokenizer {
     }

     /**
-     * Forgets what _trackInner collected, once the angle-addr or group it was collected for opens or ends
+     * Forgets the nesting collected for the operator that just opened or ended
      */
     _resetInner(): void {
         this.innerQuoted = false;
diff --git a/test/addressparser/addressparser-test.ts b/test/addressparser/addressparser-test.ts
index ab1891b6..bc545ace 100644
--- a/test/addressparser/addressparser-test.ts
+++ b/test/addressparser/addressparser-test.ts
@@ -1773,4 +1773,48 @@ describe('#addressparser', () => {
             });
         }
     });
+
+    // RFC 5322 comments nest. Ending one at the first ')' let the ')' of a nested comment
+    // close the outer one, and the rest of it was parsed as header text, the address it held
+    // included: 'Victim (x(y) <evil@evil.com>) <v@victim.com>' delivered to evil.com
+    describe('Nested comments', () => {
+        it('should end a comment only at the ")" that closes the outermost one', () => {
+            for (const [input, expected] of [
+                ['Victim (x(y) <evil@evil.com>) <v@victim.com>', [{ address: 'v@victim.com', name: 'Victim' }]],
+                ['(a(b)c; <evil@evil.com>) <v@victim.com>', [{ address: 'v@victim.com', name: 'a(b)c; <evil@evil.com>' }]],
+                ['user@example.com (outer (nested) comment)', [{ address: 'user@example.com', name: 'outer (nested) comment' }]],
+                ['a@b.com (x((y)) z)', [{ address: 'a@b.com', name: 'x((y)) z' }]],
+                ['G: (a(;)b) <x@y>;', [{ name: 'G', group: [{ address: 'x@y', name: 'a(;)b' }] }]]
+            ] as [string, any][]) {
+                assert.deepStrictEqual(addressparser(input), expected, input);
+            }
+        });
+
+        it('should not open a nested comment at an escaped "("', () => {
+            assert.deepStrictEqual(addressparser('a@b.com (x\\( y), c@d.com'), [
+                { address: 'a@b.com', name: 'x( y' },
+                { address: 'c@d.com', name: '' }
+            ]);
+        });
+
+        it('should read an unclosed nested comment to the end of the value', () => {
+            assert.deepStrictEqual(addressparser('a@b.com (x(y), c@d.com'), [{ address: 'a@b.com', name: 'x(y), c@d.com' }]);
+        });
+
+        for (const [label, build] of [
+            ['deeply nested comments', (count: number) => 'a@b.com (' + '('.repeat(count) + ')'.repeat(count) + ')'],
+            ['an unclosed run of comment openers', (count: number) => 'a@b.com ' + '('.repeat(count)]
+        ] as [string, (count: number) => string][]) {
+            it(`should tokenize ${label} in linear time`, () => {
+                const count = 400000;
+                const input = build(count);
+
+                const started = Date.now();
+                addressparser(input);
+                const elapsed = Date.now() - started;
+
+                assert.ok(elapsed < 5000, `tokenizing a ${input.length} byte value took ${elapsed}ms`);
+            });
+        }
+    });
 });
